head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil54000n";
scwin.form = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — isOk

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil54000n.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String((dma_pageContext.get("totalCountIntValue") ?? "")) + "건 [" + String((dma_pageContext.get("currentPage") ?? "")) + "/" + String((dma_pageContext.get("totalPageCount") ?? "")) + "Page]"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        scwin.form = (document.prelistPageForm || { elements: [] });
        await scwin.defaultCheck();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil54000n.onpageload' }); }
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 4개다(tx_newWrite, tx_searchCorpListByBeginIndex, tx_viewDetail, tx_submitFee) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_feeList_oncellclick
 * @description grd_feeList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_feeList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_feeList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_feeList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["listProcsStatCd"] === '33' || r["listProcsStatCd"] === '36') { await scwin.openAdjReqPop(r["bzProcsNo"], "160"); return; } if (r["listProcsStatCd"] === '30' || r["listProcsStatCd"] === '35' || r["listProcsStatCd"] === '37') { await scwin.submitFee(r["bzProcsNo"], r["listBzDtlTpCd"]); return; } return; } if (r["listProcsStatCd"] === '33'||r["listProcsStatCd"] === '36') { scwin.goPrint(r["bzProcsNo"], r["listBzDtlTpCd"]); return; }
        await scwin.viewDetail(r["bzProcsNo"], r["listBzDtlTpCd"], r["listProcsStatCd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_feeList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_newWrite_onclick
 * @description 「신규작성」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_newWrite_onclick = async function(e){
    try {
        await scwin.newWrite()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil54000n.btn_newWrite_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_63_onclick
 * @description krxpage_pagenavigator_63 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_63_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_newWriteReq').set('pageIndex', pi);
        await scwin.fncSearch();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil54000n.krxpage_pagenavigator_63_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_newWrite
 * @description new Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_newWrite = async function () {
    const sbmOptions = {
        id: "tx_newWrite",
        method: "post",
        action: "/listInvstg/listFee.do",
        ref: "dma_newWriteReq",
        target: "dlt_feeList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_searchCorpListByBeginIndex = async function () {
    const sbmOptions = {
        id: "tx_searchCorpListByBeginIndex",
        method: "post",
        action: "/listInvstg/listFee.do?method=getFeeList",
        ref: "dma_searchCorpListByBeginIndexReq",
        target: "dlt_feeList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_viewDetail
 * @description view Detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_viewDetail = async function () {
    const sbmOptions = {
        id: "tx_viewDetail",
        method: "post",
        action: "/listInvstg/listFee.do",
        ref: "dma_viewDetailReq",
        target: "dlt_feeList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_submitFee
 * @description submit Fee 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_submitFee = async function () {
    const sbmOptions = {
        id: "tx_submitFee",
        method: "post",
        action: "/listInvstg/listFee.do",
        ref: "dma_submitFeeReq",
        target: "dlt_feeList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_goPrint
 * @description go Print 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goPrint = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_goPrintReq") ? $c.util.getComponent("dma_goPrintReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name grd_feeList_fmt_column7
 * @description grd fee List fmt column7 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_feeList_fmt_column7 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_feeList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "listProcsStatCd") ?? '') : '');
        if (['33','36'].indexOf(v) >= 0) { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "수정요청" + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_feeList.column7" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_feeList_fillAct
 * @description grd fee List fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_feeList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_feeList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            let v = '-';
            if (r) { if (r["listProcsStatCd"] === '33' || r["listProcsStatCd"] === '36') { v = "수정요청"; } else if (r["listProcsStatCd"] === '30' || r["listProcsStatCd"] === '35' || r["listProcsStatCd"] === '37') { v = "제출"; } }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_feeList.fillAct' });
    }
};

/**
 * @method
 * @name newWrite
 * @description new Write 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newWrite = async function () {
    scwin.form.action = "/listInvstg/listFee.do";
    $c.util.getComponent('dma_newWriteReq').set('method', "listFeeForm");
    $c.util.getComponent('dma_newWriteReq').set('view', 'save');
    await scwin.tx_newWrite();
};

/**
 * @method
 * @name defaultCheck
 * @description default Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.defaultCheck = async function () {
    isOk = (String(((dma_pageContext.get("isOk") ?? "")) == null ? '' : ((dma_pageContext.get("isOk") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("isOk") ?? "")) == null ? '' : ((dma_pageContext.get("isOk") ?? ""))));
    if (isOk !== '') {
        if (isOk) {
            await $c.win.alert('제출되었습니다');
        } else {
            await $c.win.alert('제출시 오류가 발생했습니다.');
        }
        $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil54000/jldfil54000.xml') + null;
    }
};

/**
 * @method
 * @name fncSearch
 * @description fnc Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fncSearch = async function () {
    const pageIndex = $c.util.getComponent('dma_newWriteReq').get('pageIndex');
    $c.util.getComponent('dma_newWriteReq').set('pageIndex', pageIndex);
    await scwin.searchCorpListByBeginIndex();
};

/**
 * @method
 * @name searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCorpListByBeginIndex = async function () {
    await scwin.tx_searchCorpListByBeginIndex();
};

/**
 * @method
 * @name viewDetail
 * @description view Detail 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} listBzDtlTpCd listBzDtlTpCd
 * @param {*} view view
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewDetail = async function (bzProcsNo, listBzDtlTpCd, view) {
    let feeTp = '0004120101';
    if (listBzDtlTpCd === '62') {
        feeTp = '0004120102';
    }
    scwin.form.action = "/listInvstg/listFee.do";
    $c.util.getComponent('dma_newWriteReq').set('method', "loadListFeeInfo");
    $c.util.getComponent('dma_newWriteReq').set('bzProcsNo', bzProcsNo);
    $c.util.getComponent('dma_newWriteReq').set('listFeeAnulfeeTpCd', feeTp);
    if (view === '' || view === '30' || view === '35') {
        $c.util.getComponent('dma_newWriteReq').set('view', 'save');
    } else {
        if (view === '32' || view === '37') {
            $c.util.getComponent('dma_newWriteReq').set('view', 'view');
        }
    }
    await scwin.tx_viewDetail();
};

/**
 * @method
 * @name goPrint
 * @description go Print 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} listBzDtlTpCd listBzDtlTpCd
 * @returns {void}
 * @hidden N
 */
scwin.goPrint = function (bzProcsNo, listBzDtlTpCd) {
    let feeTp = '0004120101';
    if (listBzDtlTpCd === '62') {
        feeTp = '0004120102';
    }
    const rexName = "RLDFIL00034";
    const dataLocation = "/listInvstg/listFee.do?method=feeNewReport&bzProcsNo=" + bzProcsNo + "&feeTp=" + feeTp;
    $.ajax({ type: "POST", async: false, url: dataLocation, data: {  }, success: async function(data) {
                const result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                const form = (document.newReportForm || { elements: [] });
                $c.util.getComponent('dma_newWriteReq').set('ncomNm', result.comNm);
                $c.util.getComponent('dma_newWriteReq').set('nlstPayAmt', result.lstPayAmt);
                if (result.lstPayAmt1) {
                    $c.util.getComponent('dma_newWriteReq').set('nlstPayAmt1', result.lstPayAmt1);
                }
                if (result.lstPayAmt2) {
                    $c.util.getComponent('dma_newWriteReq').set('nlstPayAmt2', result.lstPayAmt2);
                }
                if (result.lstPayAmt3) {
                    $c.util.getComponent('dma_newWriteReq').set('nlstPayAmt3', result.lstPayAmt3);
                }
                if (result.lstPayAmt4) {
                    $c.util.getComponent('dma_newWriteReq').set('nlstPayAmt4', result.lstPayAmt4);
                }
                if (result.lstPayAmt5) {
                    $c.util.getComponent('dma_newWriteReq').set('nlstPayAmt5', result.lstPayAmt5);
                }
                if (result.lstPayAmt6) {
                    $c.util.getComponent('dma_newWriteReq').set('nlstPayAmt6', result.lstPayAmt6);
                }
                if (result.lstPayAmt7) {
                    $c.util.getComponent('dma_newWriteReq').set('nlstPayAmt7', result.lstPayAmt7);
                }
                if (result.lstPayAmt8) {
                    $c.util.getComponent('dma_newWriteReq').set('nlstPayAmt8', result.lstPayAmt8);
                }
                if (result.lstPayAmt9) {
                    $c.util.getComponent('dma_newWriteReq').set('nlstPayAmt9', result.lstPayAmt9);
                }
                $c.util.getComponent('dma_newWriteReq').set('nlstFeeAnulfeeTpCdnm', result.lstFeeAnulfeeTpCdnm);
                $c.util.getComponent('dma_newWriteReq').set('nTempleteCd', rexName);
                await scwin.tx_fn_goPrint();
            }, error: async function(request, status, error) {
                await $c.win.alert("장애발생.");
                return;
            }, complete: function() {

            } });
};

/**
 * @method
 * @name submitFee
 * @description submit Fee 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} listBzDtlTpCd listBzDtlTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submitFee = async function (bzProcsNo, listBzDtlTpCd) {
    scwin.form.action = "/listInvstg/listFee.do";
    $c.util.getComponent('dma_newWriteReq').set('method', "submitFeeInfo");
    $c.util.getComponent('dma_newWriteReq').set('status', "32");
    $c.util.getComponent('dma_newWriteReq').set('listBzDtlTpCd', listBzDtlTpCd);
    $c.util.getComponent('dma_newWriteReq').set('bzProcsNo', bzProcsNo);
    if (await $c.win.confirm('제출하시겠습니까?')) {
        await scwin.tx_submitFee();
    }
};

/**
 * @method
 * @name openAdjReqPop
 * @description open Adj Req Pop 처리
 * @param {*} prtdepoNo prtdepoNo
 * @param {String} listInvstgBzTpCd listInvstgBzTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openAdjReqPop = async function (prtdepoNo, listInvstgBzTpCd) {
    const data = { bzProcsNo: prtdepoNo, listInvstgBzTpCd: listInvstgBzTpCd, listBzDtlTpCd: "23", callbackFn: "scwin.popupCallback" };
    const options = { id: "jldfil59411", popupName: "상장공시제출시스템 수정요청", width: 900, height: 380, frameModal: "top" };
    await $c.win.openPopup("/jldfil59411/jldfil59411.xml", options, data);
};
